        backdropClose?: boolean;
        backdropTransitionDuration?: number;
        fade?: boolean;
        fullscreen?: ModalFullscreen;
        keyboard?: boolean;
        onHide?: () => boolean;
        onHidden?: () => void;
        open?: boolean;
